 "content": "def transform(grid):
    """Color the exposed end-points of 2-shapes with 8 and erase 3 separator."""
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    # The 3-colored separator is removed in the demonstrations.
    for r in range(h):
        for c in range(w):
            if a[r][c] == 3:
                a[r][c] = 0
    # Each shown motif contains an outer horizontal line of 2 cells. Mark its
    # two extreme endpoints. The motifs are spaced by five cells in 19x19 grids,
    # or occur as the pattern components of the compact 11x11 examples.
    # Find 2-components and mark the upper/lower extreme terminals as indicated
    # by the demonstrated endpoint coloring.
    seen = set()
    for r in range(h):
        for c in range(w):
            if a[r][c] != 2 or (r, c) in seen:
                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and a[yy][xx] == 2 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            # Components in the demos are glyphs; tips are isolated in a row
            # at the top or bottom boundary of that glyph.
            for yy in (min(y for y,x in comp), max(y for y,x in comp)):
                rowcells = [x for y,x in comp if y == yy]
                if len(rowcells) == 1:
                    a[yy][rowcells[0]] = 8
    return a

if __name__ == '__main__':
    pass
